import zlib, re, sys

data = open('docs/신청서.pdf', 'rb').read()
out = []
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    try:
        out.append(zlib.decompress(m.group(1)))
    except Exception:
        pass
text = b' '.join(out)
chunks = re.findall(rb'\((?:[^()\\]|\\.)*\)', text)
dec = []
for c in chunks:
    s = c[1:-1]
    s = re.sub(rb'\\([()\\])', rb'\1', s)
    for enc in ('utf-8', 'cp949', 'euc-kr'):
        try:
            dec.append(s.decode(enc))
            break
        except Exception:
            continue
print(' '.join(dec)[:8000])
